@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#100d18;--panel:#1a1422;--cream:#f6eadb;--muted:#a596a5;--pink:#ff548e;--gold:#ffcb71;--line:rgba(255,235,220,.13)}*{box-sizing:border-box}html{background:#0b0910}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% 7%,#26182b 0,#110e18 42%,#0b0910 100%);color:var(--cream);font-family:Manrope,system-ui,sans-serif;padding:0 20px 24px}.game-shell{max-width:1220px;margin:0 auto;position:relative}.topbar{height:67px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);margin-bottom:20px}.brand{display:flex;gap:10px;align-items:center;text-decoration:none;color:var(--cream);font:800 13px 'Barlow Condensed',sans-serif;letter-spacing:1.55px}.brand b{color:var(--pink)}.brand-mark{display:grid;place-items:center;width:27px;height:27px;color:#160c17;background:var(--gold);font:900 19px Georgia;transform:rotate(-7deg);box-shadow:3px 3px 0 var(--pink)}.top-center,.section-kicker,.stage-caption,.match-status,.pause-button,.site-footer,.controller-note,.modal-eyebrow,.modal-foot{font:500 10px 'DM Mono',monospace;letter-spacing:1px;color:#aa9aaa}.top-center{display:flex;align-items:center;gap:9px}.live-dot{height:7px;width:7px;background:#ff658a;box-shadow:0 0 9px #ff568d;border-radius:100%}.icon-button{width:34px;height:34px;border:1px solid var(--line);background:#211827;color:#f8bf79;font-size:17px;border-radius:50%;cursor:pointer}.game-frame{position:relative;border:1px solid rgba(255,225,209,.17);background:#120e18;box-shadow:0 18px 70px rgba(0,0,0,.35);overflow:hidden}.hud{height:91px;display:grid;grid-template-columns:1fr 102px 1fr;align-items:center;padding:0 26px;background:linear-gradient(180deg,#201823,#19131e);position:relative;z-index:2;border-bottom:1px solid rgba(255,231,211,.1)}.fighter-hud{min-width:0}.fighter-name{display:flex;align-items:center;gap:8px;font:800 17px 'Barlow Condensed',sans-serif;letter-spacing:1.5px;margin-bottom:7px;color:#fff4e8}.right-hud .fighter-name{justify-content:flex-end}.player-tag{font:500 9px 'DM Mono',monospace;color:#1b1020;background:var(--gold);padding:3px 5px;letter-spacing:0}.enemy-tag{background:#b982df;color:#1b1020}.health-track{position:relative;height:14px;background:#372531;border:1px solid rgba(255,245,233,.18);transform:skewX(-11deg);overflow:hidden}.health-fill{position:absolute;inset:0 auto 0 0;width:100%;transition:width .22s ease;background:linear-gradient(90deg,#ff4b80,#ff9b80);box-shadow:0 0 14px #f34c79}.enemy-health{left:auto;right:0;background:linear-gradient(270deg,#bf68e0,#f390a1);box-shadow:0 0 14px #bc63d4}.health-glint{position:absolute;inset:1px;background:linear-gradient(180deg,rgba(255,255,255,.2),transparent 40%);pointer-events:none}.meter-track{width:45%;height:4px;background:#36273a;margin-top:5px;margin-left:auto;position:relative}.left-hud .meter-track{margin-left:0}.meter-fill{height:100%;width:0;background:linear-gradient(90deg,#ffb95f,#ffed9a);transition:width .18s}.enemy-meter-track{margin-right:0;margin-left:auto}.enemy-meter{margin-left:auto;background:linear-gradient(90deg,#df83ff,#fbd0ff)}.hud-meta{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;color:#988996;margin-top:6px;letter-spacing:.5px}.right-hud .hud-meta{flex-direction:row-reverse}.round-display{text-align:center;height:75px;border-left:1px solid var(--line);border-right:1px solid var(--line);display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative}.round-label{color:#c6a9bc;font:9px 'DM Mono',monospace;letter-spacing:2px}.round-number{font:700 19px 'Barlow Condensed',sans-serif;color:var(--gold);line-height:20px}.timer{position:absolute;bottom:-19px;z-index:3;font:700 18px 'Barlow Condensed',sans-serif;color:#fff4e3;background:#17111c;border:1px solid rgba(255,235,220,.18);padding:1px 11px;min-width:42px}.arena-wrap{position:relative;height:min(56vw,500px);min-height:350px;background:#241628;overflow:hidden}#arena{position:absolute;inset:0;width:100%;height:100%;display:block}.round-callout{position:absolute;top:31%;left:50%;transform:translate(-50%,-50%);text-align:center;pointer-events:none;text-shadow:0 3px 22px #1a101e;transition:opacity .25s}.round-callout span,.round-callout small{display:block;font:10px 'DM Mono',monospace;letter-spacing:3px;color:#f8c46e}.round-callout strong{display:block;font:900 clamp(42px,8vw,82px)/.95 'Barlow Condensed',sans-serif;letter-spacing:1px;color:#fff0dd;text-shadow:4px 5px 0 rgba(206,70,126,.65);transform:rotate(-3deg);white-space:nowrap}.round-callout small{font-size:9px;color:#d7b6c8;margin-top:13px}.round-callout.hidden{opacity:0}.toast{position:absolute;left:50%;top:46%;transform:translate(-50%,-50%) scale(.9);font:900 52px 'Barlow Condensed',sans-serif;color:#fff1d9;text-shadow:3px 4px #f04e83;opacity:0;pointer-events:none;transition:all .16s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.arena-footer{height:42px;background:#18121c;border-top:1px solid rgba(255,231,211,.1);display:flex;align-items:center;padding:0 19px;position:relative;z-index:2}.stage-caption{display:flex;align-items:center;gap:9px;color:#e8cfd5}.stage-caption b{color:var(--gold);font-weight:500}.equalizer{height:13px;display:flex;align-items:center;gap:2px}.equalizer i{display:block;width:2px;background:#ff6393;height:7px}.equalizer i:nth-child(2){height:12px;background:var(--gold)}.equalizer i:nth-child(3){height:5px}.caption-divider{color:#594657}.match-status{position:absolute;left:50%;transform:translateX(-50%);font-size:9px}.match-status span{color:var(--pink);padding:0 5px}.pause-button{margin-left:auto;border:0;background:none;color:#b9a6b6;font-size:9px;display:flex;align-items:center;gap:7px;cursor:pointer}.pause-button:first-letter{font-size:15px;color:var(--gold)}.below-game{display:grid;grid-template-columns:1fr 1.06fr;gap:28px;padding:22px 4px 0}.section-kicker{display:flex;justify-content:space-between;margin-bottom:11px;color:#d2b7c5;font-size:9px}.section-kicker span{color:#7d6c7d}.roster{display:flex;gap:8px}.roster-card{flex:1;min-width:0;height:57px;display:flex;align-items:center;gap:8px;padding:5px 8px;background:rgba(31,23,34,.74);border:1px solid rgba(255,225,209,.12);text-align:left;color:#f9e9dc;cursor:pointer;position:relative;transition:.18s}.roster-card:hover,.roster-card.selected{border-color:rgba(255,97,145,.7);background:#2b1d2b}.roster-card.selected:after{content:'';position:absolute;bottom:-1px;left:8px;right:8px;height:2px;background:var(--pink)}.roster-swatch{flex:0 0 34px;height:43px;display:grid;place-items:center;font:900 25px Georgia;color:#251321;background:linear-gradient(145deg,#fa91b2,#7e397e);clip-path:polygon(25% 0,75% 0,100% 20%,89% 100%,10% 100%,0 20%)}.ruby-swatch{background:linear-gradient(145deg,#ffc47c,#bd305b)}.jade-swatch{background:linear-gradient(145deg,#b5e7ad,#247d75)}.roster-card b,.roster-card small{display:block;white-space:nowrap}.roster-card b{font:700 12px 'Barlow Condensed',sans-serif;letter-spacing:.8px}.roster-card small{margin-top:3px;font:8px 'DM Mono',monospace;color:#a38b9e}.select-mark{display:none;margin-left:auto;color:var(--gold);font-size:12px}.selected .select-mark{display:block}.controls-panel{border-left:1px solid var(--line);padding-left:22px}.controls-panel .section-kicker{margin-bottom:12px}.control-list{display:flex;flex-wrap:wrap;gap:7px 12px;align-items:center}.control-list span{font:9px 'DM Mono',monospace;color:#bbaaba;white-space:nowrap}.control-list kbd{font:9px 'DM Mono',monospace;padding:4px 6px;margin-right:3px;border:1px solid #554052;border-bottom-width:2px;background:#261b2a;color:#ffe4ce;min-width:20px;display:inline-block;text-align:center}.controller-note{font-size:8px;margin-top:12px;color:#837687;letter-spacing:.65px}.controller-note i{color:var(--pink);font-style:normal;padding:0 4px}.site-footer{display:flex;justify-content:space-between;border-top:1px solid var(--line);margin:18px 4px 0;padding-top:12px;font-size:8px;color:#786b7b}.modal-screen{position:absolute;inset:67px 0 0;z-index:5;display:flex;align-items:center;justify-content:center;background:rgba(13,9,17,.4);backdrop-filter:blur(2px);transition:opacity .28s,visibility .28s}.modal-screen.dismissed{opacity:0;visibility:hidden;pointer-events:none}.modal-card{width:min(440px,calc(100% - 32px));text-align:center;padding:31px 40px 23px;background:linear-gradient(145deg,rgba(36,24,39,.97),rgba(22,16,27,.98));border:1px solid rgba(255,224,202,.29);box-shadow:0 18px 60px #08060bb0;position:relative}.modal-card:before,.modal-card:after{content:'✦';position:absolute;color:var(--gold);font-size:14px}.modal-card:before{top:12px;left:14px}.modal-card:after{bottom:11px;right:14px}.modal-eyebrow{display:flex;justify-content:center;align-items:center;gap:11px;font-size:8px;color:#d9afbb}.modal-eyebrow i{font-style:normal;color:var(--gold)}.modal-title{font:900 61px/.77 'Barlow Condensed',sans-serif;letter-spacing:1px;color:#fff0df;margin:22px 0;text-shadow:3px 3px 0 #d6477d}.modal-title em{font-style:normal;color:var(--gold);font-size:55px}.modal-copy{font-size:12px;line-height:1.8;color:#c4b1c2}.modal-actions{display:flex;justify-content:center;gap:8px;margin:20px 0 18px}.primary-button,.secondary-button{height:42px;padding:0 18px;border:0;cursor:pointer;font:700 11px 'DM Mono',monospace;letter-spacing:.7px;transition:transform .15s,filter .15s}.primary-button{background:linear-gradient(90deg,#ff548e,#ff8d8a);color:#1b1020;box-shadow:0 4px 0 #a73764}.primary-button span{font-size:16px;margin-left:10px}.secondary-button{background:transparent;border:1px solid #78576e;color:#f5d4de}.primary-button:hover,.secondary-button:hover{transform:translateY(-2px);filter:brightness(1.1)}.modal-foot{border-top:1px solid var(--line);padding-top:13px;font-size:8px;display:flex;justify-content:center;gap:11px;color:#927e91}.modal-foot span:nth-child(2){color:var(--gold)}.screen-flash{position:absolute;z-index:4;inset:0;background:#fff2df;opacity:0;pointer-events:none}.screen-flash.active{animation:flash .2s ease-out}@keyframes flash{0%{opacity:.55}100%{opacity:0}}.mobile-controls{display:none}
@media(max-width:760px){body{padding:0 10px 15px}.topbar{height:52px;margin-bottom:10px}.top-center{font-size:8px;letter-spacing:.5px}.hud{height:75px;padding:0 10px;grid-template-columns:1fr 54px 1fr}.fighter-name{font-size:12px;letter-spacing:.6px;gap:4px;margin-bottom:5px}.player-tag{font-size:7px;padding:2px 3px}.hud-meta{font-size:7px}.hud-meta span:last-child{display:none}.round-display{height:62px}.round-label{font-size:7px}.round-number{font-size:15px}.timer{font-size:14px;bottom:-16px;min-width:34px}.arena-wrap{height:calc(100vw * .91);min-height:310px;max-height:440px}.arena-footer{height:36px;padding:0 9px}.stage-caption{font-size:8px;gap:5px}.match-status{font-size:7px;white-space:nowrap}.pause-button{font-size:8px}.pause-button span{display:none}.below-game{grid-template-columns:1fr;gap:16px;padding:15px 2px 0}.controls-panel{border-left:0;border-top:1px solid var(--line);padding:12px 0 0}.roster-card{height:53px;padding:4px;gap:5px}.roster-swatch{flex-basis:27px;height:37px;font-size:19px}.roster-card b{font-size:10px}.roster-card small{font-size:7px}.select-mark{font-size:9px}.control-list{gap:7px}.controller-note{margin-top:9px;font-size:7px}.site-footer{font-size:7px;margin-top:12px}.modal-screen{inset:52px 0 0}.modal-card{padding:25px 20px 20px}.modal-title{font-size:53px}.modal-title em{font-size:48px}.modal-copy{font-size:11px}.modal-actions{flex-wrap:wrap}.mobile-controls{display:flex;position:absolute;inset:auto 0 9px;justify-content:space-between;align-items:flex-end;padding:0 10px;pointer-events:none;z-index:3}.dpad,.action-pad{display:flex;gap:5px;pointer-events:auto}.dpad{align-items:flex-end}.mobile-controls button{border:1px solid #fff4e133;background:#241a2ccc;color:#fff0df;font:700 11px 'DM Mono',monospace;backdrop-filter:blur(3px);touch-action:none;user-select:none}.dpad button{width:43px;height:42px;border-radius:12px}.dpad button:nth-child(2){height:50px;color:#ffcd78}.action-pad{display:grid;grid-template-columns:repeat(2,48px);grid-template-rows:repeat(2,40px)}.action-pad button{border-radius:11px;font-size:9px}.touch-light{color:#fff!important;background:#bb4773!important}.touch-heavy{color:#fff!important;background:#82467f!important}.touch-special{color:#291522!important;background:#e8ad64!important}.touch-block{color:#fff!important;background:#43566b!important}}
@media(max-width:370px){.top-center{display:none}.roster-card b{font-size:9px}.roster-card small{font-size:6px}.control-list{gap:6px}.control-list span{font-size:8px}.action-pad{grid-template-columns:repeat(2,43px)}.dpad button{width:36px}.modal-actions{gap:6px}.primary-button,.secondary-button{padding:0 12px;font-size:10px}}
@media(hover:none) and (pointer:coarse){.mobile-controls{display:flex}}

(() => {
  'use strict';
  const canvas = document.getElementById('arena'), ctx = canvas.getContext('2d');
  const W = 960, H = 500;
  const $ = id => document.getElementById(id);
  const chars = {
    violet:{name:'VIOLET VICE',tag:'THE SHOWSTOPPER',main:'#bd4383',dark:'#572454',light:'#ffb6ca',hair:'#32192f',accent:'#ffd078',skin:'#e9ad91',style:'violet'},
    ruby:{name:'RUBY RIOT',tag:'THE WILDCARD',main:'#d34958',dark:'#6d253d',light:'#ffc17d',hair:'#531f28',accent:'#ffe17d',skin:'#e7a88d',style:'ruby'},
    jade:{name:'JADE JETT',tag:'THE ACE',main:'#328c83',dark:'#164a55',light:'#b2e4ad',hair:'#172c3c',accent:'#f2cc78',skin:'#d99978',style:'jade'},
    noir:{name:'MADAME NOIR',tag:'THE HOUSE FAVORITE',main:'#68449b',dark:'#302341',light:'#d7bbff',hair:'#211a32',accent:'#f4c778',skin:'#d89d85',style:'noir'}
  };
  let selected='violet', versus=false, running=false, paused=false, finished=false, soundOn=true, last=0, elapsed=0, round=1, wins=[0,0], toastTimeout, audioCtx;
  const input={left:false,right:false,jump:false,light:false,heavy:false,special:false,block:false};
  const p1=makeFighter('player','violet',180,1), p2=makeFighter('enemy','noir',780,-1);
  function makeFighter(side,char,x,face){return {side,char,x,y:0,vx:0,vy:0,face,health:100,meter:0,ground:true,state:'idle',anim:0,attack:null,attackCd:0,stun:0,block:false,combo:0,comboTimer:0,flash:0,rounds:0,aiWait:.6,aiAction:0};}
  function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);}
  new ResizeObserver(resize).observe(canvas); resize();
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function playTone(freq=240,dur=.07,type='triangle',vol=.035){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur);}catch{}}
  function resetFighter(f,x,face,char){Object.assign(f,{char,x,y:0,vx:0,vy:0,face,health:100,meter:f.side==='player'?f.meter:0,ground:true,state:'idle',anim:0,attack:null,attackCd:0,stun:0,block:false,combo:0,comboTimer:0,flash:0});}
  function resetRound(){round++;$('round-number').textContent=String(round).padStart(2,'0');$('footer-round').textContent=String(round).padStart(2,'0');resetFighter(p1,180,1,selected);resetFighter(p2,780,-1,versus?'jade':'noir');$('round-callout').querySelector('strong').textContent=`ROUND ${String(round).padStart(2,'0')}`;$('round-callout').classList.remove('hidden');$('round-callout').querySelector('small').textContent='GET READY';setTimeout(()=>{$('round-callout').classList.add('hidden');},1150);elapsed=0;finished=false;}
  function begin(isVersus=false){versus=isVersus;running=true;paused=false;finished=false;round=0;wins=[0,0];$('modal-screen').classList.add('dismissed');$('pause-button').innerHTML='Ⅱ <span>PAUSE</span>'; $('match-status').innerHTML=versus?'LOCAL VERSUS <span>•</span> FIRST TO TWO':'BEST OF THREE <span>•</span> FIRST TO TWO'; resetRound(); updateHud();}
  function attack(f,type){if(!running||paused||finished||f.stun>0||f.attackCd>0)return;if(type==='special'&&f.meter<35)return;const data={light:{duration:.30,hit:.12,reach:92,damage:6,cost:0},heavy:{duration:.52,hit:.22,reach:112,damage:12,cost:0},special:{duration:.70,hit:.30,reach:215,damage:18,cost:35}}[type];if(type==='special')f.meter-=data.cost;f.attack={type,t:0,hit:false,...data};f.attackCd=data.duration*.7;f.state=type;f.anim=0;playTone(type==='special'?560:type==='heavy'?190:330,type==='special'?.16:.07,type==='heavy'?'sawtooth':'triangle',.04);}
  function hit(attacker,defender){const a=attacker.attack;if(!a||a.hit||a.t<a.hit||a.t>a.hit+.12)return;const dx=defender.x-attacker.x,dist=Math.abs(dx);if(dist>a.reach+16)return;if(!defender.ground&&defender.y>85)return;a.hit=true;const guarded=defender.block&&defender.face===Math.sign(attacker.x-defender.x);const damage=guarded?Math.ceil(a.damage*.22):a.damage;defender.health=Math.max(0,defender.health-damage);defender.meter=clamp(defender.meter+(guarded?4:8),0,100);attacker.meter=clamp(attacker.meter+(guarded?3:7),0,100);if(guarded){defender.stun=.16;defender.vx=(attacker.x>defender.x?-1:1)*45;showToast('GUARD!',false);playTone(120,.06,'square',.025);}else{defender.stun=a.type==='heavy'?.36:.24;defender.vx=(attacker.x>defender.x?-1:1)*(a.type==='special'?370:a.type==='heavy'?285:170);defender.vy=a.type==='special'?-115:a.type==='heavy'?-75:-20;defender.ground=true;defender.state='hit';defender.flash=.18;attacker.combo++;attacker.comboTimer=1.1;showToast(attacker.combo>1?`${attacker.combo} HIT!`:a.type==='special'?'GLOW BREAK!':'',true);playTone(a.type==='heavy'?95:150,.1,'sawtooth',.05);if(a.type==='special')$('screen-flash').classList.add('active');}updateHud();if(defender.health<=0)endRound(attacker.side);}
  function showToast(text,show){const el=$('toast');clearTimeout(toastTimeout);if(!show||!text){el.classList.remove('show');return;}el.textContent=text;el.classList.add('show');toastTimeout=setTimeout(()=>el.classList.remove('show'),550);}
  function endRound(winner){if(finished)return;finished=true;running=false;wins[winner==='player'?0:1]++;const winnerName=winner==='player'?(chars[selected].name):versus?'JADE JETT':'MADAME NOIR';$('round-callout').querySelector('strong').textContent=winner==='player'?'ROUND!':'K.O.!';$('round-callout').querySelector('small').textContent=`${winnerName} TAKES IT`;$('round-callout').classList.remove('hidden');const won=wins[winner==='player'?0:1]>=2;updateHud();setTimeout(()=>{if(won){$('round-callout').querySelector('strong').textContent=winner==='player'?'HEADLINER!':'HOUSE WINS';$('round-callout').querySelector('small').textContent='TAP TAKE THE STAGE TO RUN IT BACK';$('modal-screen').classList.remove('dismissed');$('start-button').textContent='RUN IT BACK ↗';$('versus-button').textContent='CHANGE MATCH';}else{round--;resetRound();running=true;}},1650);}
  function updateHud(){ $('player-health').style.width=`${p1.health}%`; $('enemy-health').style.width=`${p2.health}%`; $('player-meter').style.width=`${p1.meter}%`; $('enemy-meter').style.width=`${p2.meter}%`; $('player-name').textContent=chars[selected].name;$('enemy-name').textContent=versus?'JADE JETT':'MADAME NOIR';$('player-wins').textContent=`ROUND WINS  ${wins[0]?'◆':'◇'} ${wins[0]>1?'◆':'◇'}`;$('enemy-wins').textContent=`ROUND WINS  ${wins[1]?'◆':'◇'} ${wins[1]>1?'◆':'◇'}`;}
  function keyControl(key,on){const k=key.toLowerCase();if(k==='a'||k==='arrowleft')input.left=on;if(k==='d'||k==='arrowright')input.right=on;if(k==='w'||k==='arrowup')input.jump=on;if(k==='j'||k==='x')input.light=on;if(k==='k'||k==='z')input.heavy=on;if(k==='l'||k==='c')input.special=on;if(k===' '||k==='s'||k==='arrowdown')input.block=on;}
  window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key))e.preventDefault();if(e.repeat)return;keyControl(e.key,true);if(e.key==='Escape'||e.key.toLowerCase()==='p')togglePause();});window.addEventListener('keyup',e=>keyControl(e.key,false));window.addEventListener('blur',()=>Object.keys(input).forEach(k=>input[k]=false));
  let prevButtons=[];
  function gamepadInput(){const pads=navigator.getGamepads?.()||[];const pad=pads[0];if(!pad)return;const ax=pad.axes[0]||0;input.left=ax<-.3||pad.buttons[14]?.pressed;input.right=ax>.3||pad.buttons[15]?.pressed;input.jump=!!(pad.buttons[0]?.pressed||pad.buttons[12]?.pressed);const b=pad.buttons;[['light',2],['heavy',0],['special',1],['block',4]].forEach(([name,i])=>{if(b[i]?.pressed&&!prevButtons[i]){input[name]=true;setTimeout(()=>input[name]=false,90);} });prevButtons=b.map(x=>x.pressed);if(b[9]?.pressed&&!prevButtons[9])togglePause();}
