ight:100%;display:block}.round-callout{position:absolute;top:31%;left:50%;transform:translate(-50%,-50%);text-align:center;pointer-events:none;text-shadow:0 3px 22px #1a101e;transition:opacity .25s}.round-callout span,.round-callout small{display:block;font:10px 'DM Mono',monospace;letter-spacing:3px;color:#f8c46e}.round-callout strong{display:block;font:900 clamp(42px,8vw,82px)/.95 'Barlow Condensed',sans-serif;letter-spacing:1px;color:#fff0dd;text-shadow:4px 5px 0 rgba(206,70,126,.65);transform:rotate(-3deg);white-space:nowrap}.round-callout small{font-size:9px;color:#d7b6c8;margin-top:13px}.round-callout.hidden{opacity:0}.toast{position:absolute;left:50%;top:46%;transform:translate(-50%,-50%) scale(.9);font:900 52px 'Barlow Condensed',sans-serif;color:#fff1d9;text-shadow:3px 4px #f04e83;opacity:0;pointer-events:none;transition:all .16s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.arena-footer{height:42px;background:#18121c;border-top:1px solid rgba(255,231,211,.1);display:flex;align-items:center;padding:0 19px;position:relative;z-index:2}.stage-caption{display:flex;align-items:center;gap:9px;color:#e8cfd5}.stage-caption b{color:var(--gold);font-weight:500}.equalizer{height:13px;display:flex;align-items:center;gap:2px}.equalizer i{display:block;width:2px;background:#ff6393;height:7px}.equalizer i:nth-child(2){height:12px;background:var(--gold)}.equalizer i:nth-child(3){height:5px}.caption-divider{color:#594657}.match-status{position:absolute;left:50%;transform:translateX(-50%);font-size:9px}.match-status span{color:var(--pink);padding:0 5px}.pause-button{margin-left:auto;border:0;background:none;color:#b9a6b6;font-size:9px;display:flex;align-items:center;gap:7px;cursor:pointer}.pause-button:first-letter{font-size:15px;color:var(--gold)}.below-game{display:grid;grid-template-columns:1fr 1.06fr;gap:28px;padding:22px 4px 0}.section-kicker{display:flex;justify-content:space-between;margin-bottom:11px;color:#d2b7c5;font-size:9px}.se